            clauses.append(clause)
        return clauses

    def matrix_from_3sat(instance: list, n: int) -> list:
        matrix = [[0] * n for _ in range(n)]
        for clause in instance:
            for var in clause:
                if var > 0:
                    matrix[var - 1][var - 1] += 1
                else:
                    matrix[-var - 1][-var - 1] -= 1
        return matrix

    def determinant(matrix: list) -> int:
        n = len(matrix)
        if n == 1:
            return matrix[0][0]
        det = 0
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            sign = (-1) ** (j % 2)
            det += sign * matrix[0][j] * determinant(submatrix)
        return det

    def permanent(matrix: list) -> int:
        n = len(matrix)
        if n == 1:
            return matrix[0][0]
        perm = 0
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            sign = (-1) ** (j % 2)
            perm += sign * matrix[0][j] * permanent(submatrix)
        return abs(perm)

    def count_partition_occurrences(matrix, partition):
        n = len(matrix)
        if n != len(partition):
            return 0
        count = 0
        for perm in set(permutations(range(n))):
            product = 1
            for i, p in enumerate(perm):
                product *= matrix[i][p]
            if sorted([product] * partition[i]) == sorted(matrix):
                count += 1
        return count

